const ptcgOk=id=>{id=String(id||'');const m=id.match(/^([a-z0-9]+)-([a-z0-9]+)$/i);if(!m||/[A-Z]/.test(m[1]))return false;return !/^(me\d|30th)/.test(m[1])};
