function totals(){let v=0,b=0,n=0,vb=0,nb=0,o=0;for(const c of S.collection){const w=(c.price||0)*c.qty,old=itStale(c);n+=c.qty;if(old){o+=w;continue}v+=w;if(c.buy>0){b+=c.buy*c.qty;vb+=w;nb+=c.qty}}return{v,b,n,g:vb-b,vb,nb,o}}
function snapshot(){if(window._pLoad)return;const d=today();const t=totals();if(!(t.v>0)&&S.collection.some(c=>+c.price>0))return;S.snapshots=S.snapshots.filter(s=>s.d!==d);S.snapshots.push({d,v:+t.v.toFixed(2)});S.snapshots.sort((a,b)=>a.d.localeCompare(b.d));save()}

// Keine Bilder von riskanten Hosts (Rechteinhaber/Marktplätze/Fanseiten) – stattdessen Platzhalter mit Name + Nummer
const BADIMG=/^https?:\/\/([^/]*\.)?(pokemon-card\.com|snkrdunk\.com|tcgplayer\.com|serebii\.net|pokeca\.net|pokeca-souba\.[a-z.]+|limitlesstcg\.nyc3\.cdn\.digitaloceanspaces\.com)\//i;/* v143: Kartenbilder nur von TCGdex und pokemontcg.io (EN) – alles andere wird nicht geladen */const IMGHOST=/^https:\/\/(assets\.tcgdex\.net|images\.pokemontcg\.io|images\.scrydex\.com)\//i;const safeImg=u=>u&&!BADIMG.test(u)&&(!/^https?:/i.test(u)||IMGHOST.test(u))?u:'';
const phCard=(name,num,set,lang)=>{const n=String(name||'').replace(/^✓\s*/,'').replace(/^#\S+\s+/,'').replace(/<[^>]*>/g,'');const m=n.match(/^(.*?)\s*\(([^)]*)\)$/);const a=m?m[1]:n;const LG=/^(JP|JA|DE|EN|FR|IT|ES|PT|KO|ZH)$/i;let lg=String(lang||'').trim().toUpperCase().slice(0,3);if(lg==='JA')lg='JP';let st=String(set||'').trim();const sl=st.match(/\s*\(([A-Za-z]{2})\)\s*$/);if(sl&&LG.test(sl[1])){lg=lg||sl[1].toUpperCase();st=st.slice(0,sl.index).trim()}let b=m?m[2]:'';if(b){const parts=b.split(',').map(x=>x.trim()).filter(x=>{if(LG.test(x)){lg=lg||x.toUpperCase();return false}return true});const nrm=x=>x.toLowerCase().replace(/[^a-z0-9\u3040-\u9fff]/g,'');b=parts.filter(x=>!(st&&(nrm(st).includes(nrm(x))||nrm(x).includes(nrm(st))))).join(', ');if(!st&&b){st=b;b=''}}/* v143: ein einheitlicher Platzhalter: Name, Nr., Set (+Code), Sprache – jede Angabe nur einmal */return`<div class="cardph" role="img" aria-label="${esc(a||'Karte')}: Bild folgt">${lg?`<i class="phl"${lg==='JP'?' data-jp':''}>${lg==='PT'?'🇵🇹 ':''}${esc(lg)}</i>`:''}<b>${esc(a)}</b>${b?(/^Teil [12]\/2$/.test(b)?`<span class="phteil">${esc(b)}</span>`:`<em>${esc(b)}</em>`):''}${num?`<span>Nr. ${esc(num)}</span>`:''}${st?`<em class="phs">${esc(st)}</em>`:''}<small>Bild folgt</small></div>`};
