/* v143: Verlauf nur aus Karten mit aktuellem Preis – Karten ohne Preis (z.B. JP nach Entfernen der Yen-Preise) zählen in keinem Punkt, also kein Absturz auf 0 € */function histSeries(){/* v148: gleiche Rechnung, aber linear statt quadratisch und zwischengespeichert (Klick-Verzögerung beim Tab-Wechsel) */const L=S.collection.filter(c=>+c.price>0&&!itStale(c));const td=today();
 let sig=td+'|'+S.snapshots.length+'|'+(S.snapshots[0]&&S.snapshots[0].d)+'|'+L.length;for(const c of L){const ph=c.ph||[];sig+='|'+c.price+','+(c.qty||1)+','+(c.added||'')+','+ph.length+','+(ph.length?ph[ph.length-1].d+':'+ph[ph.length-1].p:'')}
 if(histSeries._k===sig)return histSeries._v.map(p=>({...p}));
 const D=new Set([td,...S.snapshots.map(p=>p.d)]),PD=new Set();for(const c of L)for(const x of c.ph||[]){D.add(x.d);PD.add(x.d)}const ds=[...D].filter(d=>d<=td).sort();const first=S.snapshots.length?S.snapshots[0].d:td;const days=ds.filter(d=>d>=first||PD.has(d));
 const vals=new Array(days.length).fill(0);
 for(const c of L){const ph=c.ph||[],q=c.qty||1,f=ph.find(x=>x.p>0),fb=f?f.p:+c.price;let sorted=true;for(let i=1;i<ph.length;i++)if(ph[i].d<ph[i-1].d){sorted=false;break}
  let j=0,last=null;for(let k=0;k<days.length;k++){const d=days[k];if(c.added&&c.added>d)continue;let p;if(d===td)p=+c.price;else if(sorted){while(j<ph.length&&ph[j].d<=d){if(ph[j].p>0)last=ph[j].p;j++}p=last!=null?last:fb}else{p=null;for(const x of ph)if(x.d<=d&&x.p>0)p=x.p;if(p==null)p=fb}vals[k]+=p*q}}
 const out=days.map((d,k)=>({d,v:+vals[k].toFixed(2)}));/* v152: Tage vor der ersten bepreisten Karte nicht als 0-€-Punkte zeigen */while(out.length>1&&!(out[0].v>0))out.shift();histSeries._k=sig;histSeries._v=out;return out.map(p=>({...p}))}
function series(tf){const s=histSeries();if(!tf)return s;const cut=new Date(Date.now()-tf*864e5).toISOString().slice(0,10);const r=s.filter(p=>p.d>=cut);
 if(r.length<2&&s.length>=2){const prev=[...s].reverse().find(p=>p.d<cut);if(prev)return[prev,...r]}return r}
function drawChart(s){const cv=$('#chart');if(!cv.offsetParent)return;const dpr=window.devicePixelRatio||1;const W=cv.clientWidth,H=cv.clientHeight;cv.width=W*dpr;cv.height=H*dpr;const x=cv.getContext('2d');x.scale(dpr,dpr);
 let pts=s.map(p=>p.v);if(pts.length<2)pts=[pts[0]||0,pts[0]||0];const up=pts.at(-1)>=pts[0];const col=up?'#22c55e':'#ef4444';
 const mn=Math.min(...pts),mx=Math.max(...pts),r=(mx-mn)||1,px=i=>i*W/(pts.length-1),py=v=>H-14-(v-mn)/r*(H-34);
 x.beginPath();pts.forEach((v,i)=>i?x.lineTo(px(i),py(v)):x.moveTo(px(i),py(v)));x.strokeStyle=col;x.lineWidth=2.5;x.lineJoin='round';x.stroke();
 x.lineTo(W,H);x.lineTo(0,H);x.closePath();const gr=x.createLinearGradient(0,0,0,H);gr.addColorStop(0,up?'rgba(34,197,94,.35)':'rgba(239,68,68,.35)');gr.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=gr;x.fill();
 if(s.length<2){x.fillStyle='#8a93a6';x.font='12px system-ui';x.textAlign='center';x.fillText('Wertverlauf ab dem 2. Tag sichtbar',W/2,H/2-10)}}
